 34	func prepareEnableCheckpointRemoteCommand(cmd *cobra.Command, opts *EnableOptions) error {
 35		if cmd.Flags().Changed(flagCheckpointPushRemote) && cmd.Flags().Changed(flagCheckpointRemote) {
 36			return fmt.Errorf("--%s and --%s cannot be combined", flagCheckpointPushRemote, flagCheckpointRemote)
 37		}
 38		explicit := cmd.Flags().Changed(flagCheckpointPushRemote)
 39		canPrompt := !cmd.Flags().Changed(agentFlagName) && interactive.CanPromptInteractively()
 40		pending := canPrompt && !explicit && !settings.IsSetUpAny(cmd.Context())
 41		choice, err := prepareEnableCheckpointRemoteSelection(cmd.Context(), *opts, explicit, canPrompt && !pending, nil)
 42		if err != nil {
 43			cmd.SilenceUsage = true
 44			return err
 45		}
 46		choice.pending = pending
 47		opts.checkpointRemoteChoice = choice
 48		cmd.SetContext(context.WithValue(cmd.Context(), enableCheckpointRemoteKey{}, choice))
 49		return nil
 50	}
 51	
 52	func (c *enableCheckpointRemoteChoice) selectAfterAgents(ctx context.Context, opts EnableOptions, selectFn func(context.Context, []huh.Option[string]) (string, error)) error {
 53		if c == nil || !c.pending {
 54			return nil
 55		}
 56		choice, err := prepareEnableCheckpointRemoteSelection(ctx, opts, false, true, selectFn)
 57		if err != nil {
 58			return err
 59		}
 60		// Keep the pointer shared with the command's deferred destination report.
 61		*c = *choice
 62		return nil
 63	}
