107			return choice, nil
108		}
109		current := resolved.Name
110		label := fmt.Sprintf("Keep current destination: %s (%s; no settings change)", current, checkpointRemoteSourceLabel(resolved.Source))
111		if resolveErr != nil {
112			current = s.GetCheckpointPushRemote()
113			label = fmt.Sprintf("Keep invalid destination: %s (checkpoint sync remains disabled; no settings change)", current)
114		} else if eligibilityErr != nil {
115			label = fmt.Sprintf("Keep unsupported destination: %s (no configured fetch URL; no settings change)", current)
116		}
117		options := []huh.Option[string]{huh.NewOption(label, "")}
118		for _, d := range topology.destinations {
