134		}
135		if len(options) == 1 {
136			return choice, nil
137		}
138		if selectFn == nil {
139			selectFn = func(ctx context.Context, options []huh.Option[string]) (string, error) {
140				return selectEnableCheckpointRemote(ctx, options, len(topology.destinations))
141			}
142		}
143		name, err := selectFn(ctx, options)
144		if err != nil {
145			return nil, fmt.Errorf("checkpoint destination selection cancelled: %w", err)
146		}
