173	func checkpointRemoteSourceLabel(source strategy.CheckpointSyncRemoteSource) string {
174		if source == strategy.SyncRemoteSourceConfig {
175			return "configured"
176		}
177		if source == strategy.SyncRemoteSourceObserved {
178			return "previously selected"
179		}
180		return "automatic"
181	}
