335			if !dedicated && d.pinned {
336				url, effective, err := remote.PushURL(ctx, d.name)
337				if err == nil && effective {
338					fmt.Fprintf(w, "Pushes to %s still upload checkpoints to the dedicated destination: %s\n", d.name, gitremote.RedactURLOrPath(url))
339				}
340			}
341			if d.name != resolved.Name || !d.fansOut() {
342				continue
343			}
344			remoteTopology{destinations: []remoteDestination{d}, primaryIsRefs: topology.primaryIsRefs}.describeFanout(w)
345		}
346		if !dedicated && c.name == "" && resolved.Source != strategy.SyncRemoteSourceConfig {
