		cmd.SilenceUsage = true
		return err
	}
	choice.pending = pending
	opts.checkpointRemoteChoice = choice
	cmd.SetContext(context.WithValue(cmd.Context(), enableCheckpointRemoteKey{}, choice))
	return nil
}

